"""Core data structures for describing a loom and the yarns it carries."""

from dataclasses import dataclass
from typing import Dict, List, Set


@dataclass
class Yarn:
    name: str
    material: str
    diameter_mm: float
    max_float_run: int
    sett_epi: float


@dataclass
class YarnSet:
    warp_yarn: Yarn
    weft_yarn: Yarn


@dataclass
class Loom:
    shaft_count: int
    treadle_count: int
    threading: List[int]
    tieup: Dict[int, Set[int]]
    treadling: List[int]

    @property
    def end_count(self) -> int:
        return len(self.threading)

    @property
    def pick_count(self) -> int:
        return len(self.treadling)

"""Float-length checks for a woven structure.

A float is a place where one thread system skips over several picks or ends
without interlacing. Long floats snag in use, so each yarn carries its own
tolerance and a draft is checked against it before it goes to the loom.
"""

from typing import List

from loom import YarnSet


def find_max_float_run(cells: List[bool], target: bool) -> int:
    """Longest run of `target` within a single row or column of the grid."""
    longest = 0
    current = 0
    for cell in cells:
        if cell == target:
            current += 1
            longest = max(longest, current)
        else:
            current = 0
    return longest


def _column(grid, index):
    return [row[index] for row in grid]


def warp_float_limit(yarn_set: YarnSet) -> int:
    """Longest run of raised warp the fabric can tolerate before it snags."""
    return yarn_set.weft_yarn.max_float_run


def weft_float_limit(yarn_set: YarnSet) -> int:
    """Longest run of raised weft the fabric can tolerate before it snags."""
    return yarn_set.weft_yarn.max_float_run


def check_float_limits(grid, yarn_set: YarnSet):
    warnings = []
    end_count = len(grid[0]) if grid else 0

    warp_limit = warp_float_limit(yarn_set)
    for end_index in range(end_count):
        run = find_max_float_run(_column(grid, end_index), target=True)
        if run > warp_limit:
            warnings.append(
                f"warp float of {run} picks too long at end {end_index} "
                f"(limit {warp_limit})"
            )

    weft_limit = weft_float_limit(yarn_set)
    for pick_index, row in enumerate(grid):
        run = find_max_float_run(row, target=False)
        if run > weft_limit:
            warnings.append(
                f"weft float of {run} ends too long at pick {pick_index} "
                f"(limit {weft_limit})"
            )

    return warnings

"""High level workflow for evaluating a threading / treadling draft."""

from loom import Loom, YarnSet
from weave import build_interlacement_grid
from floats import check_float_limits


def run_structural_checks(grid, yarn_set: YarnSet):
    return check_float_limits(grid, yarn_set)


def evaluate_draft(loom: Loom, yarn_set: YarnSet):
    grid = build_interlacement_grid(loom)
    warnings = run_structural_checks(grid, yarn_set)
    return {
        "ends": loom.end_count,
        "picks": loom.pick_count,
        "warnings": warnings,
    }
